#!/usr/bin/env bash

# Generated by the Geo-Causal host bootstrap.
# Source this file before WSL scientific workloads.

geocausal_script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
export GEOCAUSAL_REPO="${GEOCAUSAL_REPO:-$geocausal_script_dir}"
export GEOCAUSAL_SCRATCH="${GEOCAUSAL_SCRATCH:-${XDG_CACHE_HOME:-${HOME}/.cache}/geo-causal-bench}"

# One physical GPU only.
export CUDA_VISIBLE_DEVICES=0

# Avoid JAX reserving most VRAM at process startup.
export XLA_PYTHON_CLIENT_PREALLOCATE=false

# High-churn caches stay in WSL ext4.
export JAX_COMPILATION_CACHE_DIR="$GEOCAUSAL_SCRATCH/jax"
export UV_CACHE_DIR="$GEOCAUSAL_SCRATCH/uv"
export PIP_CACHE_DIR="$GEOCAUSAL_SCRATCH/pip"
export TMPDIR="$GEOCAUSAL_SCRATCH/tmp"
export PATH="$GEOCAUSAL_SCRATCH/envs/core/bin:/usr/lib/wsl/lib:$PATH"

mkdir -p \
    "$JAX_COMPILATION_CACHE_DIR" \
    "$UV_CACHE_DIR" \
    "$PIP_CACHE_DIR" \
    "$TMPDIR"
